candidates.raw:
    adcs_vec3_t desired, cross;
    double b2, n;

    if ((momentum_error_nms == NULL) || (field_body_t == NULL) || (command == NULL) ||
        (achievable_torque_nm == NULL)) {
        return ADCS_E_NULL;
    }
    if ((!adcs_is_finite_vec3(momentum_error_nms)) || (!adcs_is_finite_vec3(field_body_t)) ||
        (!isfinite(torque_gain_s_inv)) || (!isfinite(max_dipole_a_m2)) ||
        (torque_gain_s_inv < 0.0) || (max_dipole_a_m2 < 0.0)) {
        command->command = (adcs_vec3_t){0, 0, 0};
        command->saturated_axes = 0U;
        *achievable_torque_nm = (adcs_vec3_t){0, 0, 0};
        return ADCS_E_RANGE;
    }
    b2 = adcs_vec3_dot(field_body_t, field_body_t);
    if (b2 <= ADCS_EPS_NORM * ADCS_EPS_NORM) {
        command->command = (adcs_vec3_t){0, 0, 0};
        command->saturated_axes = 0U;
        *achievable_torque_nm = (adcs_vec3_t){0, 0, 0};
        return ADCS_E_DEGENERATE;
    }
    desired = adcs_vec3_scale(momentum_error_nms, -torque_gain_s_inv);
    cross = adcs_vec3_cross(field_body_t, &desired);
    command->command = adcs_vec3_scale(&cross, 1.0 / b2);
    n = adcs_vec3_norm(&command->command);
    command->saturated_axes = 0U;
    if (n > max_dipole_a_m2) {
        command->command = adcs_vec3_scale(&command->command, max_dipole_a_m2 / n);
        command->saturated_axes = 7U;
    }
    *achievable_torque_nm = adcs_vec3_cross(&command->command, field_body_t);
    return ADCS_OK;
}

